# Archive REML policy: independent scalar-score starting value; threshold 1e-12*max(1, start).
start_tau <- function(y, v) {
  score <- function(t) {w <- 1/(v+t); mu <- sum(w*y)/sum(w); sum(w*w*(y-mu)^2) - sum(w) + sum(w*w)/sum(w)}
  if (score(0) <= 0) return(0)
  hi <- max(var(y), max(v), 1e-8); while (score(hi) > 0) hi <- hi*2
  uniroot(score, c(0, hi), tol = 1e-14, maxiter = 1000)$root
}
fit <- function(y, v, slab) {
  ctl <- list(threshold = 1e-12, maxiter = 10000, stepadj = 1)
  ctl$tau2.init <- start_tau(y, v); ctl$threshold <- 1e-12*max(1, ctl$tau2.init)
  rma(y, v, slab = slab, method = "REML", test = "z", control = ctl)
}
